// === Tab: mySketch ===
let w = 900, h = 900;
let s = 10;
let ss = 80;
let type;
let grid = 30;
let hh = (h - s*8) / grid;
let ww = (w - s*8) / grid;

let pal = ['#ECAA9C','#B1D1C6', '#2E5B8B', '#F2CA60', '#d4c7a3', '#DE7830', '#513C2C', '#1F3858', '#C9292E', '#bfb8a3'];

function mousePressed() {
	redraw();
}

function setup() {
  createCanvas(w, h);
	pixelDensity(2);
  noLoop();
  smooth();
  colorMode(HSB, 360, 100, 100, 100);
}

function draw() {
  background(220);
  shuffle(pal, true);

  var r = 24;
  var jr = random(300, 500);
  var ratio = 1.9;
  var k = r * ratio;
  var radius, alpha;

  push();
  // translate(s*4, s*4);
  noStroke();
  for(let i = 0; i < grid; i++) {
    var count = random(10,30);
    ny = i * k - r;

    var xr, dd;

    for(let j = 0; j < 11; j++) {

      nx = j * k;
      if(i % 2 == 0) {
        nx -= k/2;
      }
      nx -= s/2;

      noiseSeed(random(100));
      if(random() < 0.5) {
        dd = 1;
      } else {
        dd = -1;
      }

	   var col = color( getColor() );

      var kx = w-nx;

      var gx = abs(w/2-nx);
      var gy = abs(h/2-ny);

      if(sqrt(gx*gx + gy*gy) > jr) {
        continue;
      }

      if(random() < 0.8) {
        for(let l =0; l < count/4; l++) {

          alpha = 10;
          col.setAlpha(alpha);
          fill(col);

          radius = pow(r*1.5, map(l, 0, count/4, 1, 1.1));
          circle(nx, ny+l, radius);
          circle(kx, ny+l, radius);
        }

        if(random() < 0.36 && j != 10) {
					for(let l =0; l < count; l++) {

						alpha = map(l, 0, count*2/3, 10, 60);
						col.setAlpha(alpha);
						fill(col);

						radius = map(l, 0, count, r*1.5, 5);

						xr = 2*s*(dd * (l * 0.05));
						circle(nx+xr, ny-l*2, radius);
					}
                    noiseSeed(random(100));
					for(let l =0; l < count; l++) {

						alpha = map(l, 0, count*2/3, 10, 60);
						col.setAlpha(alpha);
						fill(col);

						radius = map(l, 0, count, r*1.5, 5);

						xr = 2*s*(dd * (l * 0.05));
						circle(kx-xr, ny-l*2, radius);
					}
				} else {
					for(let l =0; l < count; l++) {

						alpha = map(l, 0, count*2/3, 10, 60);
						col.setAlpha(alpha);
						fill(col);

						radius = map(l, 0, count, r*1.5, 5);

						circle(nx, ny-l*2, radius);
                        circle(kx, ny-l*2, radius);
					}
				}

      } else {
        for(let l =0; l < count/4; l++) {

          alpha = 10;
          col.setAlpha(alpha);
          fill(col);

          radius = pow(r*1.5, map(l, 0, count/4, 1, 1.1));
          circle(nx, ny+l, radius);
          circle(kx, ny+l, radius);
        }

        for(let l =0; l < count; l++) {

          if(l > count/2) {
            continue;
          }

          alpha = map(l, 0, count*2/3, 10, 60);
          col.setAlpha(alpha);
          fill(col);

          radius = map(l, 0, count, r*1.5, 5);
          circle(nx, ny-l*2, radius);
          circle(kx, ny-l*2, radius);
        }

        fill(220);
        ellipse(nx, ny-count-3, r*2/3+2,r*2/3-5);
        ellipse(kx, ny-count-3, r*2/3+2,r*2/3-5);
      }

    }    
  }
  pop();
  drawGrids();
  drawFrame();
}


// ------------------------------------- //
// ------------------------------------- //
// ------------------------------------- //

function drawGrids() {
  stroke(0,0,10,100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for(let i = 0; i < ty; i++) {
    cy = i * s;
    for(let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  } 
}

function drawFrame() {
  rectMode(CENTER);
  noStroke();
  fill(220);

  rect(s*2-1, h/2, s*4, h);
  rect(w-s*2+1, h/2, s*4, h);

  rect(w/2, s*2-1, w, s*4);
  rect(w/2, h-s*2+1, w, s*4);
}

function getColor(x, y) {
  var l = pal.length;
  var k = 1000;
  var cc = noise(x/k, y/k);

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l) {
    return pal[1];
  } else if (cc < 3/l) {
    return pal[2];
  } else if (cc < 4/l) {
    return pal[3];
  } else if (cc < 5/l) {
    return pal[4];
  } else if (cc < 6/l) {
    return pal[5];
  } else if (cc < 7/l) {
    return pal[6];
  } else if (cc < 8/l) {
    return pal[7];
  } else if (cc < 9/l) {
    return pal[8];
  } else {
    return pal[9];
  }
}

function getColor() {
  var l = pal.length;
  var cc = random();

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l) {
    return pal[1];
  } else if (cc < 3/l) {
    return pal[2];
  } else if (cc < 4/l) {
    return pal[3];
  } else if (cc < 5/l) {
    return pal[4];
  } else if (cc < 6/l) {
    return pal[5];
  } else if (cc < 7/l) {
    return pal[6];
  } else if (cc < 8/l) {
    return pal[7];
  } else if (cc < 9/l) {
    return pal[8];
  } else {
    return pal[9];
  }
}

